entries[65433] = { ["name"] = "Recipe: South Island Iced Tea", ["text"] = "Binds when picked up\nUse: Teaches you how to brew some South Island Iced Tea.\nRequires Cataclysm Cooking (75)\n\nSouth Island Iced Tea\nUse: Gets you tipsy and restores 18 mana over 30 sec. Must remain seated while drinking.\nSell Price:\nRequires Tropical Sunfruit , Refreshing Spring Water" }
entries[65435] = { ["name"] = "Recipe: Cauldron of Battle", ["text"] = "Binds when picked up\nUse: Teaches you how to make a Cauldron of Battle.\nRequires Cataclysm Alchemy (75)\n\nCauldron of Battle\nBinds to Warband\nUse: Creates a cauldron that raid members can use to gain the benefit of a flask appropriate to their class and talents. Cauldron has 10 uses and lasts for 10 min.\nRequires Guild\n- Friendly\nSell Price:\nRequires Flask of Steelskin , Flask of the Draconic Mind , Flask of the Winds , Flask of Titanic Strength , Deathblood Venom (8)" }
entries[65455] = { ["name"] = "Flask of Battle", ["text"] = "Conjured Item\nUnique: Guild Flask (1)\nUse: Grants the effect of a flask based on your class and talents. Lasts 1 hour and persists through death. (3 Sec Cooldown)" }
