entries[66097] = { ["name"] = "Plans: Lifeforce Hammer", ["text"] = "Binds when picked up\nUse: Teaches you how to make a Lifeforce Hammer.\nRequires Blacksmithing (425)\n\nLifeforce Hammer\nBinds when equipped\nOne-Hand Mace\n2 - 3 Damage Speed 2.60\n(1.0 damage per second)\n+12 Intellect\n+3 Stamina\n+ 2 Versatility\n+ 2 Mastery\nDurability 90 / 90\nSell Price:\nRequires Folded Obsidium (4), Elementium Bar (12), Volatile Earth (10), Volatile Water (6)\nOptional Reagents: Optional Reagent Slot (#47)" }
entries[66098] = { ["name"] = "Plans: Obsidium Executioner", ["text"] = "Binds when picked up\nUse: Teaches you how to make an Obsidium Executioner.\nRequires Blacksmithing (425)\n\nObsidium Executioner\nBinds when equipped\nTwo-Hand Sword\n8 - 14 Damage Speed 3.60\n(3.1 damage per second)\n+4 Strength\n+6 Stamina\n+ 4 Critical Strike\n+ 4 Mastery\nDurability 100 / 100\nSell Price:\nRequires Folded Obsidium (10), Elementium Bar (10), Volatile Earth (6)\nOptional Reagents: Optional Reagent Slot (#47)" }
entries[66099] = { ["name"] = "Plans: Obsidium Skeleton Key", ["text"] = "Binds when picked up\nUse: Teaches you how to make an Obsidium Skeleton Key.\nRequires Blacksmithing (425)\n\nObsidium Skeleton Key\nUse: Allows opening of locks that require up to 35 lockpicking skill. The skeleton key is consumed in the process.\nRequires Cataclysm Blacksmithing (25)\nSell Price:\nRequires Folded Obsidium (2)" }
entries[66100] = { ["name"] = "Plans: Ebonsteel Belt Buckle", ["text"] = "Binds when picked up\nUse: Teaches you how to make an Ebonsteel Belt Buckle.\nCannot be applied to items higher than level 49.\nRequires Cataclysm Blacksmithing (75)\n\nEbonsteel Belt Buckle\nUse: Permanently attach an ebonsteel belt buckle onto a belt, adding a socket to the belt.\n\nAttaching the belt buckle causes the item to become soulbound. Cannot be used on items level 0 or higher.\nSell Price:\nRequires Volatile Earth (4), Elementium Bar (4), Pyrium Bar (4)" }
entries[66101] = { ["name"] = "Plans: Pyrium Shield Spike", ["text"] = "Binds when picked up\nUse: Teaches you how to make a Pyrium Shield Spike.\nRequires Cataclysm Blacksmithing (75)\n\nPyrium Shield Spike\nBinds when equipped\nUse: Attaches a Pyrium Spike to your shield that sometimes deals 42 damage when you block with it.\n\nAttaching a Pyrium Spike to your shield causes it to become soulbound. Cannot be applied to items higher than level 320.\nRequires Pyrium Bar (5)" }
entries[66102] = { ["name"] = "Plans: Elementium Shield Spike", ["text"] = "Binds when picked up\nUse: Teaches you how to make an Elementium Shield Spike.\nRequires Blacksmithing (425)\n\nElementium Shield Spike\nUse: Attaches an Elementium Spike to your shield that deals 4 damage each time you block with it.\n\nAttaching an Elementium Spike to your shield causes it to become soulbound. Cannot be applied to items higher than level 320.\nRequires Elementium Bar (15)" }
entries[66103] = { ["name"] = "Plans: Pyrium Weapon Chain", ["text"] = "Binds when picked up\nUse: Teaches you how to make a Pyrium Weapon Chain.\nRequires Cataclysm Blacksmithing (50)\n\nPyrium Weapon Chain\nBinds when equipped\nUse: Attaches a chain to your weapon, reducing the duration of Disarm effects by 50% and increasing your haste by 12. Does not stack with other similar effects. Attaching the weapon chain causes the weapon to become soulbound. Cannot be applied to items higher than level 320.\nRequires Pyrium Bar" }
entries[66104] = { ["name"] = "Plans: Hardened Elementium Hauberk", ["text"] = "Binds when picked up\nUse: Teaches you how to make a Hardened Elementium Hauberk.\nRequires Cataclysm Blacksmithing (65)\n\nHardened Elementium Hauberk\nBinds when equipped\nChest Plate\n16 Armor\n+3 [Strength or Intellect]\n+6 Stamina\n+ 3 Parry\n+ 4 Critical Strike\n\nPrismatic Socket\nSocket Bonus: + 1 Parry\n\nDurability 165 / 165\nSell Price:\nRequires Hardened Elementium Bar (5), Truegold (6), Chaos Orb (3)\nOptional Reagents: Optional Reagent Slot (#49)" }
